import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
   .version 8.0
   .target sm_89
   .address_size 64
   .extern .shared .align 16 .b8 smem[];
   .visible .entry convtrans3d_fwd(
       .param .u64 x_ptr,
       .param .u64 w_ptr,
       .param .u64 b_ptr,
       .param .u64 out_ptr,
       .param .u32 pB,
       .param .u32 pIC,
       .param .u32 pOC,
       .param .u32 pD,
       .param .u32 pH,
       .param .u32 pW,
       .param .u32 pOD,
       .param .u32 pOH,
       .param .u32 pOW,
       .param .u32 pkD,
       .param .u32 pkH,
       .param .u32 pkW,
       .param .u32 pStrideD,
       .param .u32 pStrideH,
       .param .u32 pStrideW,
       .param .u32 pPadD,
       .param .u32 pPadH,
       .param .u32 pPadW,
       .param .u32 pDilD,
       .param .u32 pDilH,
       .param .u32 pDilW,
       .param .u32 pOutPadD,
       .param .u32 pOutPadH,
       .param .u32 pOutPadW,
       .param .u32 pGroups
   )
   {
       .reg .pred  %p<24>;
       .reg .s32   %r<220>;
       .reg .s64   %rd<140>;
       .reg .f32   %f<12>;
       // Load pointers
       ld.param.u64 %rd1, [x_ptr];
       ld.param.u64 %rd2, [w_ptr];
       ld.param.u64 %rd3, [b_ptr];
       ld.param.u64 %rd4, [out_ptr];
       // Load scalar params
       ld.param.u32 %r30, [pB];
       ld.param.u32 %r31, [pIC];
       ld.param.u32 %r32, [pOC];
       ld.param.u32 %r33, [pD];
       ld.param.u32 %r34, [pH];
       ld.param.u32 %r35, [pW];
       ld.param.u32 %r36, [pOD];
       ld.param.u32 %r37, [pOH];
       ld.param.u32 %r38, [pOW];
       ld.param.u32 %r39, [pkD];
       ld.param.u32 %r40, [pkH];
       ld.param.u32 %r41, [pkW];
       ld.param.u32 %r42, [pStrideD];
       ld.param.u32 %r43, [pStrideH];
       ld.param.u32 %r44, [pStrideW];
       ld.param.u32 %r45, [pPadD];
       ld.param.u32 %r46, [pPadH];
       ld.param.u32 %r47, [pPadW];
       ld.param.u32 %r48, [pDilD];
       ld.param.u32 %r49, [pDilH];
       ld.param.u32 %r50, [pDilW];
       ld.param.u32 %r150, [pOutPadD];
       ld.param.u32 %r151, [pOutPadH];
       ld.param.u32 %r152, [pOutPadW];
       ld.param.u32 %r51, [pGroups];
       // Compute output x, y from grid
       mov.u32 %r1, %tid.x;
       mov.u32 %r2, %ntid.x;
       mov.u32 %r3, %ctaid.x;
       mad.lo.s32 %r4, %r3, %r2, %r1;        // ow index in %r4
       mov.u32 %r5, %tid.y;
       mov.u32 %r6, %ntid.y;
       mov.u32 %r7, %ctaid.y;
       mad.lo.s32 %r8, %r7, %r6, %r5;        // oh index in %r8
       mov.u32 %r9,  %tid.z;
       mov.u32 %r10, %ntid.z;
       mov.u32 %r11, %ctaid.z;
       // tilesD = (OD + blockDim.z - 1) / blockDim.z
       add.s32 %r52, %r36, %r10;
       add.s32 %r52, %r52, -1;
       div.s32 %r53, %r52, %r10;             // tilesD
       // d_tile = blockIdx.z % tilesD; t = blockIdx.z / tilesD
       rem.s32 %r54, %r11, %r53;             // d_tile
       div.s32 %r55, %r11, %r53;             // t
       // oc = t % OC; b = t / OC
       rem.s32 %r56, %r55, %r32;             // oc
       div.s32 %r57, %r55, %r32;             // b
       // od = d_tile * blockDim.z + threadIdx.z
       mad.lo.s32 %r58, %r54, %r10, %r9;     // od
       // oc_per_group and ic_per_group
       div.s32 %r59, %r32, %r51;    // ocpg
       div.s32 %r60, %r31, %r51;    // icpg
       // g = oc / ocpg; ocg = oc % ocpg
       div.s32 %r61, %r56, %r59;    // g
       rem.s32 %r64, %r56, %r59;    // ocg
       // ic_start = g * icpg; ic_end = ic_start + icpg
       mul.lo.s32 %r62, %r61, %r60;
       add.s32    %r63, %r62, %r60;
       // Compute linear thread id and threads per block
       // r110 = linear tid, r111 = threads per block
       mul.lo.s32 %r103, %r2, %r6;           // ntid.x * ntid.y
       mul.lo.s32 %r104, %r5, %r2;           // ty * ntid.x
       add.s32    %r110, %r1, %r104;         // tx + ty*ntid.x
       mad.lo.s32 %r110, %r9, %r103, %r110;  // + tz*(ntid.x*ntid.y)
       mul.lo.s32 %r111, %r2, %r6;
       mul.lo.s32 %r111, %r111, %r10;        // threads per block
       // total_elems to preload into shared memory: icpg * kD * kH * kW
       mul.lo.s32 %r112, %r60, %r39;
       mul.lo.s32 %r112, %r112, %r40;
       mul.lo.s32 %r113, %r112, %r41;        // total_elems
       // chunk = kD * kH * kW
       mul.lo.s32 %r130, %r39, %r40;
       mul.lo.s32 %r130, %r130, %r41;        // chunk
       // Shared memory base
       mov.u64 %rd60, smem;
       // Cooperative preload of weights for this (ocg) across all ic, kd, kh, kw using cp.async
       mov.s32 %r114, %r110;                 // idx = linear tid
   PL_LOOP:
       setp.ge.s32 %p10, %r114, %r113;
       @%p10 bra PL_DONE;
       // Compute global weight index using compact mapping:
       // ic_rel = sidx / chunk; rem = sidx - ic_rel*chunk
       div.s32     %r160, %r114, %r130;      // ic_rel
       mul.lo.s32  %r161, %r160, %r130;      // ic_rel * chunk
       sub.s32     %r161, %r114, %r161;      // rem within chunk
       // t_val = (ic_start + ic_rel)*ocpg + ocg
       add.s32     %r162, %r62, %r160;       // ic_start + ic_rel
       mul.lo.s32  %r162, %r162, %r59;       // * ocpg
       add.s32     %r162, %r162, %r64;       // + ocg
       // global index = t_val*chunk + rem
       cvt.s64.s32 %rd70, %r162;
       cvt.s64.s32 %rd71, %r130;
       mul.lo.s64  %rd70, %rd70, %rd71;      // t_val * chunk
       cvt.s64.s32 %rd72, %r161;
       add.s64     %rd70, %rd70, %rd72;      // + rem
       shl.b64     %rd70, %rd70, 2;          // *4 bytes
       add.s64     %rd71, %rd2, %rd70;       // w address
       // Shared memory destination address
       cvt.s64.s32 %rd80, %r114;
       shl.b64     %rd80, %rd80, 2;
       add.s64     %rd81, %rd60, %rd80;
       // Asynchronous copy from global to shared (4 bytes)
       cp.async.ca.shared.global [%rd81], [%rd71], 4;
       // next idx
       add.s32 %r114, %r114, %r111;
       bra PL_LOOP;
   PL_DONE:
       cp.async.commit_group;
       cp.async.wait_group 0;
       bar.sync 0;
       // Preload bias into shared memory once per CTA (if provided)
       // Use the slot right after the cooperatively loaded weights: smem + total_elems*4
       setp.ne.s64 %p18, %rd3, 0;           // bias ptr != 0 ?
       @!%p18 bra NO_BIAS_PRELOAD;
       // Only linear thread 0 performs the global bias load and stores to shared memory
       setp.eq.s32 %p19, %r110, 0;          // linear tid == 0 ?
       @!%p19 bra NO_BIAS_PRELOAD;
       // global bias address: b_ptr + oc*4
       cvt.s64.s32 %rd30, %r56;
       shl.b64     %rd30, %rd30, 2;
       add.s64     %rd31, %rd3, %rd30;
       ld.global.f32 %f3, [%rd31];
       // shared bias address: smem + total_elems*4
       cvt.s64.s32 %rd90, %r113;
       shl.b64     %rd90, %rd90, 2;
       add.s64     %rd91, %rd60, %rd90;
       st.shared.f32 [%rd91], %f3;
   NO_BIAS_PRELOAD:
       bar.sync 0;
       // Precompute frequently used 64-bit dims and per-CTA b*IC
       cvt.s64.s32 %rd96, %r33; // D
       cvt.s64.s32 %rd97, %r34; // H
       cvt.s64.s32 %rd98, %r35; // W
       mul.lo.s32 %r170, %r57, %r31; // b*IC
       setp.lt.s32 %p0, %r4,  %r38;
       setp.lt.s32 %p1, %r8,  %r37;
       and.pred   %p0, %p0, %p1;
       setp.lt.s32 %p1, %r58, %r36;
       and.pred   %p0, %p0, %p1;
       @!%p0 bra END;
       // Accumulator
       mov.f32 %f0, 0f00000000;
       // Adjust od/oh/ow by output padding for transposed conv mapping
       sub.s32 %r146, %r58, %r150;
       sub.s32 %r147, %r8,  %r151;
       sub.s32 %r148, %r4,  %r152;
       // kd loop init
       // Fast-path selection for common case: stride==1, dilation==1, output_padding==0
       setp.eq.s32 %p11, %r42, 1;            // strideD == 1
       setp.eq.s32 %p12, %r43, 1;            // strideH == 1
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r44, 1;            // strideW == 1
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r48, 1;            // dilD == 1
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r49, 1;            // dilH == 1
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r50, 1;            // dilW == 1
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r150, 0;           // outPadD == 0
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r151, 0;           // outPadH == 0
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r152, 0;           // outPadW == 0
       and.pred   %p11, %p11, %p12;
       @!%p11 bra SLOW_PATH;                 // if not all conditions met, use slow path
       // FAST PATH: stride=1, dilation=1, outpad=0
       mov.s32 %r70, 0;
   KD_LOOP_FAST:
       setp.ge.s32 %p2, %r70, %r39;
       @%p2 bra KD_DONE_FAST;
       // id = od + padD - kd
       sub.s32    %r72, %r45, %r70;
       add.s32    %r74, %r58, %r72;
       // bounds: 0 <= id < D
       setp.lt.s32 %p4, %r74, 0;
       @%p4 bra KD_CONT_FAST;
       setp.ge.s32 %p4, %r74, %r33;
       @%p4 bra KD_CONT_FAST;
       // kh loop
       mov.s32 %r75, 0;
   KH_LOOP_FAST:
       setp.ge.s32 %p5, %r75, %r40;
       @%p5 bra KH_DONE_FAST;
       // ih = oh + padH - kh
       sub.s32    %r77, %r46, %r75;
       add.s32    %r79, %r8,  %r77;
       // bounds: 0 <= ih < H
       setp.lt.s32 %p6, %r79, 0;
       @%p6 bra KH_CONT_FAST;
       setp.ge.s32 %p6, %r79, %r34;
       @%p6 bra KH_CONT_FAST;
       // kw loop
       mov.s32 %r80, 0;
   KW_LOOP_FAST:
       setp.ge.s32 %p7, %r80, %r41;
       @%p7 bra KW_DONE_FAST;
       // iw0 = ow + padW - kw
       sub.s32    %r82, %r47, %r80;
       add.s32    %r84, %r4,  %r82;
       // bounds: 0 <= iw0 < W
       setp.lt.s32 %p1, %r84, 0;
       @%p1 bra KW_CONT_FAST;
       setp.ge.s32 %p1, %r84, %r35;
       @%p1 bra KW_CONT_FAST;
       // Try vectorized step over 4 kw if possible
       add.s32    %r181, %r80, 3;          // kw + 3
       setp.lt.s32 %p12, %r181, %r41;      // kw+3 < kW ?
       @!%p12 bra KW_SCALAR_BODY_FAST;
       sub.s32    %r182, %r84, 3;          // iw3 = iw0 - 3
       setp.lt.s32 %p13, %r182, 0;         // iw3 >= 0 ?
       @%p13 bra KW_SCALAR_BODY_FAST;
       // ic loop (vectorized over 4 kw)
       mov.s32 %r85, %r62;
   IC_LOOP_FAST_VEC:
       setp.ge.s32 %p2, %r85, %r63;
       @%p2 bra IC_DONE_FAST_VEC;
       // row base bytes: ((((b*IC + ic)*D + id)*H + ih)*W) * 4
       add.s32    %r86, %r170, %r85;      // b*IC + ic
       cvt.s64.s32 %rd10, %r86;
       mul.lo.s64  %rd12, %rd10, %rd96;   // *D
       cvt.s64.s32 %rd13, %r74;           // id
       add.s64     %rd12, %rd12, %rd13;   // +id
       mul.lo.s64  %rd12, %rd12, %rd97;   // *H
       cvt.s64.s32 %rd15, %r79;           // ih
       add.s64     %rd12, %rd12, %rd15;   // +ih
       mul.lo.s64  %rd12, %rd12, %rd98;   // *W
       shl.b64     %rd14, %rd12, 2;       // *4 bytes
       // load 4 contiguous x values at iw3..iw0
       cvt.s64.s32 %rd16, %r182;          // iw3
       shl.b64     %rd16, %rd16, 2;
       add.s64     %rd20, %rd14, %rd16;
       add.s64     %rd20, %rd1, %rd20;
       ld.global.ca.v4.f32 {%f1, %f2, %f3, %f4}, [%rd20];
       // load 4 weights from shared memory starting at kw0
       sub.s32    %r95, %r85, %r62;       // ic_rel
       mul.lo.s32 %r96, %r95, %r39;       // *kD
       add.s32    %r96, %r96, %r70;       // + kd
       mul.lo.s32 %r96, %r96, %r40;       // *kH
       add.s32    %r96, %r96, %r75;       // + kh
       mul.lo.s32 %r96, %r96, %r41;       // *kW
       add.s32    %r183, %r96, %r80;      // + kw
       cvt.s64.s32 %rd25, %r183;
       shl.b64     %rd25, %rd25, 2;
       add.s64     %rd26, %rd60, %rd25;
       // Vectorized shared load when 16B aligned, else scalar
       and.b32     %r184, %r183, 3;
       setp.eq.s32 %p14, %r184, 0;
       @!%p14 bra W_SMEM_SCALAR;
       ld.shared.v4.f32 {%f5, %f6, %f7, %f8}, [%rd26];
       bra W_SMEM_DONE;
   W_SMEM_SCALAR:
       ld.shared.f32 %f5, [%rd26];        // w0
       add.s64     %rd27, %rd26, 4;
       ld.shared.f32 %f6, [%rd27];        // w1
       add.s64     %rd28, %rd27, 4;
       ld.shared.f32 %f7, [%rd28];        // w2
       add.s64     %rd29, %rd28, 4;
       ld.shared.f32 %f8, [%rd29];        // w3
   W_SMEM_DONE:
       // accumulate: x4*w0 + x3*w1 + x2*w2 + x1*w3
       fma.rn.f32 %f0, %f4, %f5, %f0;
       fma.rn.f32 %f0, %f3, %f6, %f0;
       fma.rn.f32 %f0, %f2, %f7, %f0;
       fma.rn.f32 %f0, %f1, %f8, %f0;
       add.s32 %r85, %r85, 1;
       bra IC_LOOP_FAST_VEC;
   IC_DONE_FAST_VEC:
       add.s32 %r80, %r80, 4;
       bra KW_LOOP_FAST;
   // scalar fallback when vector step not possible
   KW_SCALAR_BODY_FAST:
       // ic loop
       mov.s32 %r85, %r62;
   IC_LOOP_FAST:
       setp.ge.s32 %p2, %r85, %r63;
       @%p2 bra IC_DONE_FAST;
       // input linear index: (((b*IC + ic)*D + id)*H + ih)*W + iw
       add.s32    %r86, %r170, %r85;  // b*IC + ic
       cvt.s64.s32 %rd10, %r86;      // (b*IC+ic)
       mul.lo.s64  %rd12, %rd10, %rd96; // *D
       cvt.s64.s32 %rd13, %r74;      // id
       add.s64     %rd12, %rd12, %rd13; // +id
       mul.lo.s64  %rd12, %rd12, %rd97; // *H
       cvt.s64.s32 %rd15, %r79;      // ih
       add.s64     %rd12, %rd12, %rd15; // +ih
       mul.lo.s64  %rd12, %rd12, %rd98; // *W
       cvt.s64.s32 %rd17, %r84;      // iw0
       add.s64     %rd12, %rd12, %rd17; // +iw
       shl.b64     %rd12, %rd12, 2;     // *4 bytes
       add.s64     %rd20, %rd1, %rd12;  // x address
       ld.global.ca.f32 %f1, [%rd20];
       // shared weight index for ic_rel, kd, kh, kw
       sub.s32    %r95, %r85, %r62;       // ic_rel
       mul.lo.s32 %r96, %r95, %r39;       // *kD
       add.s32    %r96, %r96, %r70;       // + kd
       mul.lo.s32 %r96, %r96, %r40;       // *kH
       add.s32    %r96, %r96, %r75;       // + kh
       mul.lo.s32 %r96, %r96, %r41;       // *kW
       add.s32    %r96, %r96, %r80;       // + kw
       cvt.s64.s32 %rd25, %r96;
       shl.b64     %rd25, %rd25, 2;       // *4 bytes
       add.s64     %rd26, %rd60, %rd25;   // smem addr
       ld.shared.f32 %f2, [%rd26];
       fma.rn.f32 %f0, %f1, %f2, %f0;
       add.s32 %r85, %r85, 1;
       bra IC_LOOP_FAST;
   IC_DONE_FAST:
   KW_CONT_FAST:
       add.s32 %r80, %r80, 1;
       bra KW_LOOP_FAST;
   KW_DONE_FAST:
   KH_CONT_FAST:
       add.s32 %r75, %r75, 1;
       bra KH_LOOP_FAST;
   KH_DONE_FAST:
   KD_CONT_FAST:
       add.s32 %r70, %r70, 1;
       bra KD_LOOP_FAST;
   KD_DONE_FAST:
       bra KD_AFTER;
   // SLOW PATH: general case
   SLOW_PATH:
       // Adjust od/oh/ow by output padding for transposed conv mapping
       // (already computed above as r146, r147, r148)
       mov.s32 %r70, 0;
   KD_LOOP_SLOW:
       setp.ge.s32 %p2, %r70, %r39;
       @%p2 bra KD_DONE_SLOW;
       // id0 = (od - outPadD) + padD - kd*dilD
       mul.lo.s32 %r71, %r70, %r48;     // kd * dilD
       sub.s32    %r72, %r45, %r71;     // padD - kd*dilD
       add.s32    %r72, %r146, %r72;    // id0
       // if (id0 % strideD != 0) continue
       rem.s32 %r73, %r72, %r42;
       setp.ne.s32 %p3, %r73, 0;
       @%p3 bra KD_CONT_SLOW;
       // id = id0 / strideD
       div.s32 %r74, %r72, %r42;
       // if (id < 0 || id >= D) continue
       setp.lt.s32 %p4, %r74, 0;
       @%p4 bra KD_CONT_SLOW;
       setp.ge.s32 %p4, %r74, %r33;
       @%p4 bra KD_CONT_SLOW;
       // kh loop
       mov.s32 %r75, 0;
   KH_LOOP_SLOW:
       setp.ge.s32 %p5, %r75, %r40;
       @%p5 bra KH_DONE_SLOW;
       // ih0 = (oh - outPadH) + padH - kh*dilH
       mul.lo.s32 %r76, %r75, %r49;
       sub.s32    %r77, %r46, %r76;
       add.s32    %r77, %r147, %r77;
       // if (ih0 % strideH != 0) continue
       rem.s32 %r78, %r77, %r43;
       setp.ne.s32 %p6, %r78, 0;
       @%p6 bra KH_CONT_SLOW;
       // ih = ih0 / strideH
       div.s32 %r79, %r77, %r43;
       // if (ih < 0 || ih >= H) continue
       setp.lt.s32 %p6, %r79, 0;
       @%p6 bra KH_CONT_SLOW;
       setp.ge.s32 %p6, %r79, %r34;
       @%p6 bra KH_CONT_SLOW;
       // kw loop
       mov.s32 %r80, 0;
   KW_LOOP_SLOW:
       setp.ge.s32 %p7, %r80, %r41;
       @%p7 bra KW_DONE_SLOW;
       // iw0 = (ow - outPadW) + padW - kw*dilW
       mul.lo.s32 %r81, %r80, %r50;
       sub.s32    %r82, %r47, %r81;
       add.s32    %r82, %r148, %r82;
       // if (iw0 % strideW != 0) continue
       rem.s32 %r83, %r82, %r44;
       setp.ne.s32 %p1, %r83, 0;
       @%p1 bra KW_CONT_SLOW;
       // iw = iw0 / strideW
       div.s32 %r84, %r82, %r44;
       // if (iw < 0 || iw >= W) continue
       setp.lt.s32 %p1, %r84, 0;
       @%p1 bra KW_CONT_SLOW;
       setp.ge.s32 %p1, %r84, %r35;
       @%p1 bra KW_CONT_SLOW;
       // ic loop
       mov.s32 %r85, %r62;
   IC_LOOP_SLOW:
       setp.ge.s32 %p2, %r85, %r63;
       @%p2 bra IC_DONE_SLOW;
       // input linear index: (((b*IC + ic)*D + id)*H + ih)*W + iw
       add.s32    %r86, %r170, %r85;  // b*IC + ic
       cvt.s64.s32 %rd10, %r86;      // (b*IC+ic)
       mul.lo.s64  %rd12, %rd10, %rd96; // *D
       cvt.s64.s32 %rd13, %r74;      // id
