PTX_SOURCE = r"""
   .version 8.0
   .target sm_89
   .address_size 64
   .extern .shared .align 16 .b8 smem[];
   .visible .entry convtrans3d_fwd(
       .param .u64 x_ptr,
       .param .u64 w_ptr,
       .param .u64 b_ptr,
       .param .u64 out_ptr,
       .param .u32 pB,
