       mov.u32 %r1, %tid.x;
       mov.u32 %r2, %ntid.x;
       mov.u32 %r3, %ctaid.x;
       mad.lo.s32 %r4, %r3, %r2, %r1;        // ow index in %r4
       mov.u32 %r5, %tid.y;
       mov.u32 %r6, %ntid.y;
       mov.u32 %r7, %ctaid.y;
       mad.lo.s32 %r8, %r7, %r6, %r5;        // oh index in %r8
       mov.u32 %r9,  %tid.z;
       mov.u32 %r10, %ntid.z;
       mov.u32 %r11, %ctaid.z;
