       mov.f32 %f0, 0f00000000;
       // Adjust od/oh/ow by output padding for transposed conv mapping
       sub.s32 %r146, %r58, %r150;
       sub.s32 %r147, %r8,  %r151;
       sub.s32 %r148, %r4,  %r152;
       // kd loop init
       // Fast-path selection for common case: stride==1, dilation==1, output_padding==0
       setp.eq.s32 %p11, %r42, 1;            // strideD == 1
       setp.eq.s32 %p12, %r43, 1;            // strideH == 1
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r44, 1;            // strideW == 1
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r48, 1;            // dilD == 1
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r49, 1;            // dilH == 1
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r50, 1;            // dilW == 1
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r150, 0;           // outPadD == 0
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r151, 0;           // outPadH == 0
       and.pred   %p11, %p11, %p12;
       setp.eq.s32 %p12, %r152, 0;           // outPadW == 0
       and.pred   %p11, %p11, %p12;
